def shortest_path(graph, source, target):
    # Distances is a dictionary to store the shortest distance from the source to each node.
    # The path is a dictionary to store the shortest path to each node.
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # This dictionary stores the previous node in the shortest path from the source to the current node.
    path = {source: None}

    # The priority queue will store tuples of (current distance, current node).
    from heapq import heappush, heappop
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_node == target:
            # Reconstruct the path from the target node to the source node
            reconstructed_path = []
            while current_node:
                reconstructed_path.append(current_node)
                current_node = path[current_node]
            return (current_distance, list(reversed(reconstructed_path)))

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = current_node
                heappush(priority_queue, (distance, neighbor))

    # If we have exhausted the priority queue without finding the target, it's unreachable.
    return (float('inf'), None)
