import math

def shortest_path(graph, source, target):
    # Initialize distances and predecessors
    distances = {node: math.inf for node in graph}
    distances[source] = 0
    predecessors = {node: None for node in graph}

    # Queue for BFS
    queue = deque([source])

    while queue:
        current = queue.popleft()

        for neighbour, weight in graph[current]:
            distance_through_current = distances[current] + weight

            if distance_through_current < distances[neighbour]:
                distances[neighbour] = distance_through_current
                predecessors[neighbour] = current
                queue.append(neighbour)

    # If there is no path from source to target
    if distances[target] == math.inf:
        return float("inf"), None

    # Reconstruct the path
    path = deque()
    current = target
    while current:
        path.appendleft(current)
        current = predecessors[current]

    return distances[target], list(path)
