from collections import deque

def shortest_path(graph, source, target):
    # If the graph is empty or the source is the target, no path is needed
    if not graph or source == target:
        return (0, [source])

    # Initialize the distance and parent dictionaries for shortest path
    distances = {node: float('inf') for node in graph}
    parents = {node: None for node in graph}
    distances[source] = 0

    # Initialize a queue with the source node
    queue = deque([source])

    while queue:
        current_node = queue.popleft()

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance_through_current = distances[current_node] + weight

            # If a shorter path is found, update the distance and parent
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                parents[neighbor] = current_node
                queue.append(neighbor)

    # If there's no path from source to target, return infinity and None
    if distances[target] == float('inf'):
        return (float('inf'), None)

    # Reconstruct the path
    path = deque()
    current_node = target
    while current_node is not None:
        path.appendleft(current_node)
        current_node = parents[current_node]
    return (distances[target], list(path))

