    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))
    return graph

# Helper function to check the correctness of the shortest_path function
def check(edges, source, target):
    graph = create_graph(edges)
    result = shortest_path(graph, source, target)
    print(f"Shortest path from {source} to {target}:")
    print(f"Distance: {result[0]}, Path: {result[1]}")

# Example usage
