    ('A', 'B', 1), ('A', 'C', 4), ('B', 'C', 2), ('B', 'D', 5), ('C', 'D', 1),
    ('C', 'E', 2), ('D', 'E', 3), ('E', 'F', 4), ('D', 'F', 2)
]
check(edges, 'A', 'F')
