from collections import defaultdict, deque
from heapq import hechost

def shortest_path(graph, source, target):
    # Set up the graph as a dictionary of adjacency lists
    unvisited_nodes = defaultdict(lambda: float('inf'))
    unvisited_nodes[source] = 0
    previous_nodes = {}

    # Priority queue to handle the shortest path
    priority_queue = deque([source])

    while priority_queue:
        current_node = priority_queue.popleft()

        # If we reached the target, reconstruct the path
        if current_node == target:
            path = []
            while current_node in previous_nodes:
                path.append(current_node)
                current_node = previous_nodes[current_node]
            path.append(source)
            return (unvisited_nodes[target], list(reversed(path)))

        for neighbor, weight in graph[current_node]:
            distance_through_current_node = unvisited_nodes[current_node] + weight
            if distance_through_current_node < unvisited_nodes[neighbor]:
                unvisited_nodes[neighbor] = distance_through_current_node
                previous_nodes[neighbor] = current_node
                priority_queue.append(neighbor)

    # If we exit the loop, the target is unreachable.
    return (float("inf"), None)

